use std::time::Duration;
use chrono::Utc;
use crate::{domain::{managed_workload::ManagedWorkload,managed_workload_operation::{ManagedWorkloadOperation,ManagedWorkloadOperationState,ManagedWorkloadDispatchState},managed_workload_prepare::{parse_prepare,fingerprint,DeploymentFingerprint}},infrastructure::{managed_workload_trust::{trust_probe_command,parse_trust_probe,ACTION_ROOT},ssh::{RemoteExecutor,RemoteOutputLimits,SshTarget}},monitoring::maintenance_coordinator::{DeviceMaintenanceCoordinator,MaintenanceOperationKind},storage::{managed_workload_repository::{ManagedWorkloadRepository,JsonManagedWorkloadRepository},managed_workload_operation_repository::JsonManagedWorkloadOperationRepository}};
const LIMITS:RemoteOutputLimits=RemoteOutputLimits{stdout:32*1024,stderr:16*1024}; const TIMEOUT:Duration=Duration::from_secs(15);
#[derive(Debug,Clone)] pub struct PreparedWorkload { pub operation:ManagedWorkloadOperation,pub change_count:u32 }
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum PrepareError { Unavailable, Conflict, Trust, Protocol, Transport, Persistence }
fn verification(w:&ManagedWorkload)->Vec<String>{let mut v=Vec::new();if let Some(p)=&w.compose_project{v.push(format!("compose:{p}"))}v.extend(w.required_compose_services.iter().map(|s|format!("service:{s}")));v.extend(w.required_service_health_ids.iter().map(|s|format!("health:{s}")));v}
pub fn prepare_with(dir:&std::path::Path,target:&SshTarget,workload_id:&str,executor:&dyn RemoteExecutor,coordinator:&DeviceMaintenanceCoordinator)->Result<PreparedWorkload,PrepareError>{let workloads=JsonManagedWorkloadRepository::new(dir).load();let w=workloads.workloads.into_iter().find(|w|w.id==workload_id).filter(|w|w.enabled&&w.device_id==target.host).ok_or(PrepareError::Unavailable)?;let _claim=coordinator.try_claim(&w.device_id,MaintenanceOperationKind::WorkloadDeploy).ok_or(PrepareError::Conflict)?;let trust=executor.execute_bounded(target,&trust_probe_command(&w.action_id).map_err(|_|PrepareError::Trust)?,TIMEOUT,LIMITS).map_err(|_|PrepareError::Transport)?;let action=parse_trust_probe(&w.action_id,&trust.stdout).map_err(|_|PrepareError::Trust)?;let command=format!("'{ACTION_ROOT}/{}' prepare",w.action_id);let reply=executor.execute_bounded(target,&command,TIMEOUT,LIMITS).map_err(|_|PrepareError::Transport)?;let plan=parse_prepare(&reply.stdout).map_err(|_|PrepareError::Protocol)?;let fp=fingerprint(&w.id,w.config_revision,&action.sha256,&plan.target_revision,&verification(&w));let now=Utc::now().to_rfc3339();let op=ManagedWorkloadOperation{schema_version:1,id:uuid::Uuid::new_v4().to_string(),device_id:w.device_id,workload_id:w.id,action_id:w.action_id,config_revision:w.config_revision,trusted_action_digest:action.sha256,target_revision:plan.target_revision.as_str().into(),deployment_fingerprint:fp.0,transient_unit_id:None,dispatch_state:ManagedWorkloadDispatchState::NotAttempted,state:ManagedWorkloadOperationState::Prepared,created_at:now.clone(),prepared_at:Some(now),started_at:None,observation_deadline:None,completed_at:None,failure:None};JsonManagedWorkloadOperationRepository::new(dir).save(&op).map_err(|_|PrepareError::Persistence)?;Ok(PreparedWorkload{operation:op,change_count:plan.change_count})}
